const _cache = Object.create(null);

/** 取指定档位 loader 的二进制数据 (Uint8Array), 结果会缓存。 */
export function getLoaderBytes(key) {
  if (!(key in EFLASH_LOADERS)) {
    throw new Error('未内置该档位的 eflash_loader: ' + key);
  }
  if (_cache[key]) return _cache[key];
  const bin = atob(EFLASH_LOADERS[key].b64);
  const u8 = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) u8[i] = bin.charCodeAt(i);
  _cache[key] = u8;
  return u8;
}

/** 当前内置了哪些档位。 */
export function loaderKeys() {
  return Object.keys(EFLASH_LOADERS);
}
